import { defineStore } from 'pinia'
import { computed, ref } from 'vue'
import { mockUsers, type DemoUser } from '../mock/users'

const STORAGE_KEY = 'aoqin-demo-user'

function readStoredUser() {
  if (typeof window === 'undefined') return null
  const raw = window.localStorage.getItem(STORAGE_KEY)
  if (!raw) return null

  try {
    return JSON.parse(raw) as DemoUser
  } catch {
    window.localStorage.removeItem(STORAGE_KEY)
    return null
  }
}

export const useAuthStore = defineStore('auth', () => {
  const currentUser = ref<DemoUser | null>(readStoredUser())

  const roleLabel = computed(() => currentUser.value?.roleName || '未登录')

  function login(userId: string) {
    const user = mockUsers.find((item) => item.id === userId) || mockUsers[0]
    currentUser.value = user
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(user))
    }
  }

  function logout() {
    currentUser.value = null
    if (typeof window !== 'undefined') {
      window.localStorage.removeItem(STORAGE_KEY)
    }
  }

  return {
    currentUser,
    roleLabel,
    login,
    logout,
  }
})

