async () => {
  const routes = ['/dashboard','/reserve/collection','/planning/scheme','/planning/profile','/planning/version','/planning/output','/assistant'];
  const widths = [1440, 1280, 1024];
  const results = [];
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    for (const route of routes) {
      await page.goto(`http://127.0.0.1:5173${route}`);
      await page.waitForTimeout(250);
      const h1 = document.querySelector('h1')?.textContent?.trim() || '';
      const overflow = document.documentElement.scrollWidth - document.documentElement.clientWidth;
      const sections = document.querySelectorAll('.page-section').length;
      results.push({ width, route, h1, overflow, sections });
    }
  }
  return results;
}

